let data = $input.item.json;

// 1. Умный поиск выбранной комплектации (смотрим в qualification_context)
let qc = data.qualification_context || {};
let cached = qc.cached_json || {};
let req = data.user_request || cached.user_request || {};

// Достаем ID: приоритет на прямой ключ в qualification_context
let selectedId = qc.complectation_id || req.selected_complectation_id || cached.complectation_id;
let selectedName = req.selected_complectation_name;

// 2. Ищем массив всех машин
let rawComps = [];
if (cached.complectations) {
    rawComps = cached.complectations;
} else if (data.complectations) {
    rawComps = data.complectations;
}

// 3. Чистим и ФИЛЬТРУЕМ
let cleanComplectations = [];
if (Array.isArray(rawComps)) {
    let cleaned = rawComps.map(comp => {
        let c = Object.assign({}, comp);

        // Удаляем тяжелые данные для экономии контекста (токенов)
        delete c.features;
        delete c.images;
        delete c.stock_details;
        delete c.stock_colors;
        delete c.specs;

        // Мы НЕ удаляем c.price, так как он уже содержит:
        // MSRP (Price old), cash_bonus (Cash in hook), base_price (Price new),
        // credit_price и tradein_price.

        return c;
    });

    // Если нашли конкретный ID, оставляем только эту машину
    if (selectedId) {
        cleanComplectations = cleaned.filter(comp => String(comp.id) === String(selectedId));
    } 

    // Запасной вариант по имени, если по ID ничего не нашлось
    if (cleanComplectations.length === 0 && selectedName) {
        cleanComplectations = cleaned.filter(comp => 
            comp.name === selectedName || comp.full_name === selectedName
        );
    }

    // Если всё еще пусто — отдаем весь очищенный список
    if (cleanComplectations.length === 0) {
        cleanComplectations = cleaned;
    }
}

// 4. Формируем финальный объект (Разделяем данные для промпта и контекст ИИ)
return {
    ...data,

    ai_clean_context: {
        "user_id": data.user_id || qc.user_id || "",
        "deal_id": data.deal_id || qc.deal_id || "",
        "model": data.model || qc.model || "",
        "user_data": Object.assign({}, cached.user_data || {}, data.user_data || {}),
        "user_request": req,
        "complectations": cleanComplectations // Теперь тут 5 уровней цены для каждой машины
    }
};

